INSERT INTO feature VALUES('places','effects','Access at a place','temporary-access','partial','uncommon','mainstream languages','An access lends one element of a held list at an index read where it stands, the view at the list''s element type; an exclusive view writes the element back at its index and leaves the rest of the list as it was; a held value that is no list is refused by name, and an index naming no element stops the run at the access. An index `ys.#[i]` of an unheld list holds the list for its own access. The lend stays per held slot until a linear token names its place.','core-term core-checker runtime-emitter surface-lowering','corpus/model/control/accessor-place.gandr corpus/pathological/control/accessor-place.gandr corpus/model/control/accessor-method.gandr','corpus/ledger/features/places.gandr','#1184');
